mapper.select:
SELECT COUNT(*)
FROM ticket_stock
WHERE travel_date >= #{startDate}
  AND travel_date < #{endDateExclusive}

SELECT id, travel_date, train_id, segment_index, seat_type,
       from_station_id, to_station_id,
       total_count, sold_count, remaining_count, version, updated_at
FROM ticket_stock
WHERE travel_date = #{travelDate}
  AND train_id = #{trainId}
  AND seat_type = #{seatType}
  AND segment_index BETWEEN #{fromSegmentIndex}
                        AND #{toSegmentIndex}
ORDER BY segment_index

SELECT id, travel_date, train_id, segment_index, seat_type,
       from_station_id, to_station_id,
       total_count, sold_count, remaining_count, version, updated_at
FROM ticket_stock
WHERE travel_date >= #{startDate}
  AND travel_date < #{endDateExclusive}
  AND id > #{lastId}
ORDER BY id
LIMIT #{limit}
